-- LearnerApplicationReview
-- A table that stores admissions review and evaluation workflow facts associated with a learner
-- application, including review stage, review status, reviewer context, score or rating, review
-- dates, source raw workflow values, and source lineage. This table is separate from
-- LearnerApplicationDecision, which records the formal institutional admissions outcome.
CREATE TABLE admissions.learner_application_review (
    tenant_identifier                                UUID NOT NULL,
    learner_application_identifier                   TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    review_stage_identifier                          TEXT,
    review_status_identifier                         TEXT,
    assigned_reviewer_person_identifier              TEXT,
    last_reviewer_person_identifier                  TEXT,
    review_assigned_date                             TIMESTAMP WITH TIME ZONE,
    review_started_date                              TIMESTAMP WITH TIME ZONE,
    review_completed_date                            TIMESTAMP WITH TIME ZONE,
    review_updated_date                              TIMESTAMP WITH TIME ZONE,
    evaluation_score                                 NUMERIC,
    evaluation_score_maximum                         NUMERIC,
    review_comment_text                              TEXT,
    source_raw_review_stage                          TEXT,
    source_raw_review_status                         TEXT,
    source_raw_assigned_reviewer                     TEXT,
    source_raw_last_reviewer                         TEXT,
    source_raw_evaluation_score                      TEXT,
    source_raw_decision_stage_identifier             INTEGER,
    source_raw_decision_status_identifier            INTEGER,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_learner_application_review PRIMARY KEY (tenant_identifier, learner_application_identifier, sequence_number)
);
COMMENT ON TABLE admissions.learner_application_review IS 'A table that stores admissions review and evaluation workflow facts associated with a learner application, including review stage, review status, reviewer context, score or rating, review dates, source raw workflow values, and source lineage. This table is separate from LearnerApplicationDecision, which records the formal institutional admissions outcome.';
COMMENT ON COLUMN admissions.learner_application_review.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN admissions.learner_application_review.learner_application_identifier IS 'Identifier for the learner application being reviewed.';
COMMENT ON COLUMN admissions.learner_application_review.sequence_number IS 'Sequence number for multiple review rows associated with the application.';
COMMENT ON COLUMN admissions.learner_application_review.review_stage_identifier IS 'Reference-code value identifying the stage of the admissions review process.';
COMMENT ON COLUMN admissions.learner_application_review.review_status_identifier IS 'Reference-code value identifying the status of the admissions review process.';
COMMENT ON COLUMN admissions.learner_application_review.assigned_reviewer_person_identifier IS 'Tenant-scoped person/staff identifier for the reviewer or user assigned to review the application, where resolvable.';
COMMENT ON COLUMN admissions.learner_application_review.last_reviewer_person_identifier IS 'Tenant-scoped person/staff identifier for the most recent reviewer, where resolvable.';
COMMENT ON COLUMN admissions.learner_application_review.review_assigned_date IS 'Date and time the review or application decision workflow item was assigned.';
COMMENT ON COLUMN admissions.learner_application_review.review_started_date IS 'Date and time review activity began.';
COMMENT ON COLUMN admissions.learner_application_review.review_completed_date IS 'Date and time the review activity was completed.';
COMMENT ON COLUMN admissions.learner_application_review.review_updated_date IS 'Date and time the review workflow state was last updated in the source or operational process.';
COMMENT ON COLUMN admissions.learner_application_review.evaluation_score IS 'Lightweight review or evaluation score associated with the application review.';
COMMENT ON COLUMN admissions.learner_application_review.evaluation_score_maximum IS 'Maximum possible score for the lightweight evaluation score, where available.';
COMMENT ON COLUMN admissions.learner_application_review.review_comment_text IS 'Limited review comment or summary text; not a full rubric or comment-history model.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_review_stage IS 'Source-system review stage value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_review_status IS 'Source-system review status value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_assigned_reviewer IS 'Source-system assigned reviewer/user value preserved when the person cannot be resolved.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_last_reviewer IS 'Source-system last reviewer/user value preserved when the person cannot be resolved.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_evaluation_score IS 'Source-system evaluation score value preserved as supplied.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_decision_stage_identifier IS 'Source-system decision-stage identifier preserved as workflow lineage, not as a formal decision type.';
COMMENT ON COLUMN admissions.learner_application_review.source_raw_decision_status_identifier IS 'Source-system decision-status identifier preserved as workflow lineage, not as a formal decision type.';
COMMENT ON COLUMN admissions.learner_application_review.source_system_identifier IS 'Source system from which the review row originated or can be reconciled.';
COMMENT ON COLUMN admissions.learner_application_review.source_system_key_value IS 'Source-system key value for the review row.';
COMMENT ON COLUMN admissions.learner_application_review.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN admissions.learner_application_review.created_date IS 'Date and time record was created';
COMMENT ON COLUMN admissions.learner_application_review.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN admissions.learner_application_review.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN admissions.learner_application_review.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN admissions.learner_application_review.deleted_date IS 'Date and time record was deleted';

