CREATE TABLE admissions.learner_application_status_history (
    tenant_identifier                                UUID NOT NULL,
    learner_application_identifier                   TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    application_status_identifier                    TEXT NOT NULL,
    application_status_date                          DATE NOT NULL,
    application_status_reason_identifier             TEXT,
    application_status_reason_text                   TEXT,
    current_status_indicator                         BOOLEAN NOT NULL DEFAULT FALSE,
    source_raw_application_status                    TEXT,
    source_raw_application_status_reason             TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_learner_application_status_history PRIMARY KEY (tenant_identifier, learner_application_identifier, sequence_number)
);
COMMENT ON TABLE admissions.learner_application_status_history IS 'A table tracking status changes over the life of a learner application.';
COMMENT ON COLUMN admissions.learner_application_status_history.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN admissions.learner_application_status_history.learner_application_identifier IS 'Tenant-scoped unique identifier for the learner application.';
COMMENT ON COLUMN admissions.learner_application_status_history.sequence_number IS 'Sequence number for this status history row within the learner application';
COMMENT ON COLUMN admissions.learner_application_status_history.application_status_identifier IS 'Unique identifier for the application workflow status';
COMMENT ON COLUMN admissions.learner_application_status_history.application_status_date IS 'Date the application status became effective or was recorded';
COMMENT ON COLUMN admissions.learner_application_status_history.application_status_reason_identifier IS 'Unique identifier for the application status reason';
COMMENT ON COLUMN admissions.learner_application_status_history.application_status_reason_text IS 'Free-text explanation of the application status reason';
COMMENT ON COLUMN admissions.learner_application_status_history.current_status_indicator IS 'Indicates whether this row represents the current application status';
COMMENT ON COLUMN admissions.learner_application_status_history.source_raw_application_status IS 'Raw application status value from the source system';
COMMENT ON COLUMN admissions.learner_application_status_history.source_raw_application_status_reason IS 'Raw application status reason value from the source system';
COMMENT ON COLUMN admissions.learner_application_status_history.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN admissions.learner_application_status_history.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN admissions.learner_application_status_history.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN admissions.learner_application_status_history.created_date IS 'Date and time record was created';
COMMENT ON COLUMN admissions.learner_application_status_history.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN admissions.learner_application_status_history.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN admissions.learner_application_status_history.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN admissions.learner_application_status_history.deleted_date IS 'Date and time record was deleted';

-- LearnerApplicationWithdrawal
-- A table recording withdrawal-specific details for learner applications when withdrawal has its
-- own business process, source-system payload, reason detail, reversal, or reporting requirements.
CREATE TABLE admissions.learner_application_withdrawal (
    tenant_identifier                                UUID NOT NULL,
    learner_application_identifier                   TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    withdrawal_date                                  DATE NOT NULL,
    withdrawal_effective_date                        DATE,
    application_withdrawal_reason_identifier         TEXT,
    withdrawal_reason_text                           TEXT,
    reinstated_indicator                             BOOLEAN NOT NULL DEFAULT FALSE,
    reinstated_date                                  DATE,
    source_raw_withdraw_reason                       TEXT,
    source_raw_withdrawal_status                     TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_learner_application_withdrawal PRIMARY KEY (tenant_identifier, learner_application_identifier, sequence_number)
);
COMMENT ON TABLE admissions.learner_application_withdrawal IS 'A table recording withdrawal-specific details for learner applications when withdrawal has its own business process, source-system payload, reason detail, reversal, or reporting requirements.';
COMMENT ON COLUMN admissions.learner_application_withdrawal.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN admissions.learner_application_withdrawal.learner_application_identifier IS 'Tenant-scoped unique identifier for the learner application.';
COMMENT ON COLUMN admissions.learner_application_withdrawal.sequence_number IS 'Sequence number for this withdrawal row within the learner application';
COMMENT ON COLUMN admissions.learner_application_withdrawal.withdrawal_date IS 'Date the withdrawal was recorded or requested';
COMMENT ON COLUMN admissions.learner_application_withdrawal.withdrawal_effective_date IS 'Date the withdrawal became effective';
COMMENT ON COLUMN admissions.learner_application_withdrawal.application_withdrawal_reason_identifier IS 'Unique identifier for the application withdrawal reason';
COMMENT ON COLUMN admissions.learner_application_withdrawal.withdrawal_reason_text IS 'Free-text explanation of the withdrawal reason';
COMMENT ON COLUMN admissions.learner_application_withdrawal.reinstated_indicator IS 'Indicates whether the withdrawn application was reinstated';
COMMENT ON COLUMN admissions.learner_application_withdrawal.reinstated_date IS 'Date the withdrawn application was reinstated';
COMMENT ON COLUMN admissions.learner_application_withdrawal.source_raw_withdraw_reason IS 'Raw withdrawal reason value from the source system';
COMMENT ON COLUMN admissions.learner_application_withdrawal.source_raw_withdrawal_status IS 'Raw withdrawal status value from the source system';
COMMENT ON COLUMN admissions.learner_application_withdrawal.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN admissions.learner_application_withdrawal.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN admissions.learner_application_withdrawal.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN admissions.learner_application_withdrawal.created_date IS 'Date and time record was created';
COMMENT ON COLUMN admissions.learner_application_withdrawal.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN admissions.learner_application_withdrawal.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN admissions.learner_application_withdrawal.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN admissions.learner_application_withdrawal.deleted_date IS 'Date and time record was deleted';
